-- Finer muscles per exercise (delt heads, upper/mid/lower chest, ...), used by the
-- muscle heatmap. Generated by scripts/build-muscle-detail.py from vendor/free-exercise-db
-- (rules reviewed in docs/muscle-split-review.md). A null detail means the exercise has no
-- finer assignment and the heatmap uses its primary_muscles / secondary_muscles as they are.
alter table public.exercises
  add column primary_detail text[],
  add column secondary_detail text[];

update public.exercises e
set primary_detail = v.primary_detail, secondary_detail = v.secondary_detail
